import json,html
from pathlib import Path
ROOT=Path(__file__).parent.parent/'output';out=ROOT/'mobile-disposition-verification'
read=lambda n:json.loads((out/n).read_text())
cases=[read(n+'.json') for n in ['returned','rejected','rejected-level2']]
phases=['return-action','return2-action','returned-view','correct','level1','level2','reject-action','rejected-view','reject2-level1','reject2-action','reject2-view','published'];ui=[read(p+'-ui.json') for p in phases]
cleanup=read('fixture-cleanup.json');preserved=json.loads((ROOT/'ooru-meeting-audit/verification/preservation.json').read_text())
assert all(s['status']=='passed' for s in [*cases,*ui,preserved]) and cleanup['status']=='completed';assert cases[0]['return_count']==2
checks=['Return at level 1 requires a reason, shows the feedback to the officer, preserves the same intake and makes it editable without publishing.','Officer corrects the community in the native UI, saves it, reloads to verify persistence and resubmits the same household. GPS, member identity, head link and all surveyed values remain intact.','After the first approval, level 2 returns the record for another correction. The second UI correction and resubmission restart review at level 1.','The corrected record publishes only after both new independent approvals. Both return events and final approval remain in history.','Separate permanent-rejection cases at levels 1 and 2 remain final and locked. UI editing/resubmission controls are absent; direct save and finalize API attempts are rejected. Neither case creates a master household.','Returned and rejected card/list views, feedback, correction form, resubmission confirmation, decision controls and published master views pass at 1440px desktop and 390px mobile widths. No checked page has overflow, clipped summary text, raw underscore labels or JavaScript errors.']
links=''.join('<li><a href="'+p+'-ui.json">'+html.escape(p)+'</a></li>' for p in phases)
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mobile returns and rejections verification</title><style>body{{font:16px/1.6 system-ui;background:#f1f5f0;color:#173e34;margin:0}}main{{max-width:1000px;margin:24px auto;padding:28px;background:white;border:1px solid #d2dfd3;border-radius:16px}}h1,h2,a{{color:#155e50}}li{{margin:10px 0}}img{{width:100%;max-width:390px;border:1px solid #d2dfd3;border-radius:12px}}figure{{display:inline-block;vertical-align:top;margin:12px;max-width:390px}}</style><main><h1>Mobile return and rejection workflows: passed</h1><p>13 November 2026 · Three isolated fictional submissions replayed the latest physical Android interview with fresh test IDs through the authenticated mobile submission endpoint and scheduled native import. This run tests disposition workflows and browser layouts; it does not claim a new hardware capture.</p><ul>'''+''.join('<li>'+html.escape(c)+'</li>' for c in checks)+f'''</ul><p>Passed {sum(len(r['checks']) for r in ui)} UI view/action checks using the registration officer and both approver accounts.</p><h2>Correction made</h2><p>The submission confirmation previously said, “If you submit your application you cannot modified further.” It now accurately explains: “Submit this registration for review. You can make changes if a reviewer returns it for correction.” The confirmation heading punctuation was also corrected. The native translation and presentation changes were deployed and the second resubmission retested.</p><h2>Cleanup and preservation</h2><p>Only the three UUID-tracked fictional households, their members, approval attempts and test submissions were removed after evidence was archived. Historical reconciliation passed: {preserved['native_rows_verified']} native rows and {preserved['awe_rows_verified']} original approval-history rows unchanged. Master totals returned to {preserved['households']} households and {preserved['individuals']} individuals. The phone was not modified in this run.</p><h2>Evidence</h2><p><a href="returned.json">Return and resubmission</a> · <a href="rejected.json">First-level rejection</a> · <a href="rejected-level2.json">Second-level rejection</a> · <a href="fixture-cleanup.json">Cleanup</a></p><ul>{links}</ul><figure><img src="reject2-action-actions-390.png" alt="Second-level permanent rejection controls"><figcaption>Second-level rejection controls</figcaption></figure></main></html>'''
(out/'verification.html').write_text(page,encoding='utf-8');print('Built mobile return/rejection verification report')
